reference_sql:
select r.finished_at as last_successful_check, r.trigger_type, s.release_date
from igac.sync_runs r join igac.cadastral_snapshots s on s.snapshot_id = r.snapshot_id
where r.status = 'success' order by r.finished_at desc, r.run_id desc limit 1;

with selected as (select snapshot_id from igac.sync_runs where status = 'success' and snapshot_id is not null order by finished_at desc, run_id desc limit 1)
select s.snapshot_id, (select count(*) from igac.parcels p where p.snapshot_id = s.snapshot_id) as parcels,
(select count(*) from igac.buildings b where b.snapshot_id = s.snapshot_id) as buildings from selected s;

select (started_at at time zone 'UTC')::date as utc_day, status, trigger_type, count(*) as runs
from igac.sync_runs where started_at >= ((date_trunc('day', current_timestamp at time zone 'UTC') at time zone 'UTC') - interval '6 days') and started_at <= current_timestamp and status in ('success', 'failed')
group by (started_at at time zone 'UTC')::date, status, trigger_type order by utc_day, status, trigger_type;
